import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import 'package:sehatak/app_router.dart';
import 'package:sehatak/core/models/eye/eye_models.dart';
import 'package:sehatak/core/services/eye_service.dart';
const _c=Color(0xFF9C27B0);
class EyeDoctorsScreen extends StatelessWidget{const EyeDoctorsScreen({super.key});@override Widget build(BuildContext context){const specialties=['الكل','شبكية','قرنية','ليزك','أطفال','جلوكوما'];return Scaffold(appBar:AppBar(title:const Text('أطباء العيون')),body:StreamBuilder<List<EyeDoctor>>(stream:EyeService().streamDoctors(),builder:(context,s){if(s.hasError)return Center(child:Text('تعذر تحميل الأطباء: ${s.error}'));final data=s.data??[];return Column(children:[SizedBox(height:52,child:ListView.separated(padding:const EdgeInsets.symmetric(horizontal:12,vertical:8),scrollDirection:Axis.horizontal,itemCount:specialties.length,separatorBuilder:(_,__)=>const SizedBox(width:8),itemBuilder:(_,i)=>ChoiceChip(label:Text(specialties[i]),selected:i==0,onSelected:(_){if(i>0)context.push('${AppRouter.eyeDoctors}?specialty=${Uri.encodeComponent(specialties[i])}');}))),Expanded(child:data.isEmpty?const Center(child:Text('لا توجد بيانات متاحة حالياً')):ListView.builder(itemCount:data.length,itemBuilder:(_,i)=>Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:6),child:ListTile(onTap:()=>context.push(AppRouter.eyeDoctorDetail.replaceFirst(':id',data[i].id)),title:Text(data[i].name,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${data[i].specialty} • ${data[i].experienceYears} سنوات خبرة'),leading:const CircleAvatar(backgroundColor:Color(0x149C27B0),child:Icon(Icons.visibility,color:_c)),trailing:Text(data[i].rating.toStringAsFixed(1)))))]);});}}
